import {lessons,rateTabs,rateSkills} from './rates.js';
import {stats} from './progress.js';
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function rateControls(unitMode,mode,history,mistakes){return `<section class="unit-controls card" aria-label="Rates and ratios practice settings"><div class="eyebrow">Unit 2 · Rates &amp; Ratios</div><div class="unit-modes" role="group" aria-label="Learning mode">${['Learn','Practice','Quiz'].map(name=>`<button type="button" data-study="${name}" aria-pressed="${unitMode===name}" class="${unitMode===name?'selected':''}">${name}${name==='Quiz'?' · 10 questions':''}</button>`).join('')}<button type="button" id="rate-mistakes" ${mistakes?'':'disabled'}>Practice My Mistakes (${mistakes})</button></div><p class="muted">${unitMode==='Quiz'?'Every topic, with three proportional word problems. Your first answer counts; retries still help you learn.':unitMode==='Mistakes'?'Revisit your missed questions. A correct first answer removes a question from your saved mistakes.':'Unlimited questions. Select a topic or use the adaptive mix to focus on skills that need practice.'}</p>${unitMode==='Quiz'||unitMode==='Mistakes'?'':`<label class="small">TOPIC<select id="rate-topic"><option value="rates" ${mode==='rates'?'selected':''}>Adaptive topic mix</option>${rateTabs.map(([id,label])=>`<option value="${id}" ${id===mode?'selected':''}>${label}</option>`).join('')}</select></label>`}<details class="unit-mastery"><summary>Topic progress &amp; mastery</summary><div class="unit-progress">${rateTabs.map(([id,label],i)=>{const s=stats(history.filter(r=>r.skill===rateSkills[i]));return `<div><strong>${label}</strong><span>${s.mastery} · ${s.correct}/${s.attempted} first try · ${s.accuracy}%</span></div>`}).join('')}</div></details></section>`}
export function rateLearning(p,unitMode){const [title,concept,example]=lessons[p.topic.replace('rate-','')];return `<details class="factoring-help rate-help" ${unitMode==='Learn'?'open':''}><summary>Learn how · ${title}</summary><p>${escape(concept)}</p><div class="explanation"><strong>Worked example</strong>\n${escape(example)}</div></details>`}
export function rateVisual(p){if(!p.visual)return '';return `<div class="ratio-visual">${p.visual.map(group=>`<div><strong>${escape(group.name)}</strong><div class="object-group" role="img" aria-label="${escape(group.count)} ${escape(group.name)}">${Array.from({length:group.count},()=>`<span aria-hidden="true">${escape(group.symbol)}</span>`).join('')}</div></div>`).join('')}</div>`}
export function rateInput(p,{answer,selected,done}){
 const disabled=done?'disabled':'';
 const ratio=p.kind==='ratio'||p.kind==='equivalent',listInput=p.kind==='list',touch=ratio||listInput,separator=listInput?',':':',entryName=listInput?'list':'ratio';
 let choices='';
 if(['choice','select','common-gcf'].includes(p.kind))choices=`<fieldset class="rate-options"><legend>${p.kind==='choice'?'Choose one answer':p.kind==='common-gcf'?'1. Select every common factor':'Select ALL correct answers'}</legend><div class="${p.kind==='common-gcf'||p.options.length>12?'factor-grid':'reasonchoices'}">${p.options.map(o=>`<button type="button" data-rate-option="${escape(o.value)}" aria-pressed="${selected.includes(o.value)}" class="${selected.includes(o.value)?'selected':''}" ${disabled}>${escape(o.label)}</button>`).join('')}</div></fieldset>`;
 const needsInput=!['choice','select'].includes(p.kind);
 const label=p.kind==='common-gcf'?'2. Greatest common factor':p.kind==='time'?'Clock time (include AM or PM)':p.kind==='ratio'||p.kind==='equivalent'?'Your ratio (a:b)':p.kind==='list'?'Your list (comma-separated numbers)':'Your answer';
 const placeholder=p.kind==='time'?'9:24 AM':p.kind==='ratio'||p.kind==='equivalent'?'2 : 3':p.kind==='list'?'2, 4, 6':'Enter a number or fraction';
 return `${choices}${needsInput?`<label for="answer" class="rate-answer-label">${label}${p.units?' · '+escape(p.units):''}</label><div class="inputwrap"><input id="answer" type="text" autocomplete="off" inputmode="${touch?'none':p.kind==='number'||p.kind==='common-gcf'?'decimal':'text'}" enterkeyhint="done" placeholder="${placeholder}" value="${escape(answer)}" ${disabled}></div>${touch?`<p class="tiny muted">Tap the numbers and ${listInput?'comma':'colon'} below to build your ${entryName}.</p><div class="ratio-keypad" role="group" aria-label="${listInput?'List':'Ratio'} number pad">${['1','2','3','4','5','6','7','8','9',separator,'0','backspace','clear'].map(key=>`<button type="button" data-ratio-key="${key}" class="${key===separator?'ratio-colon':key==='clear'?'ratio-clear':''}" aria-label="${key===separator?(listInput?'Insert comma':'Insert colon'):key==='backspace'?'Delete last digit':key==='clear'?'Clear '+entryName:key}" ${disabled}>${key==='backspace'?'⌫':key==='clear'?'Clear':key}</button>`).join('')}</div><output id="ratio-readout" class="ratio-readout" aria-live="polite" aria-atomic="true">${answer?'Your '+entryName+': '+escape(answer):''}</output>`:''}`:''}<div class="answerrow"><button class="primary" ${disabled}>Check answer</button></div>`;
}
export function editRatio(value,key,start=value.length,end=start){
 start=Math.max(0,Math.min(start,value.length));end=Math.max(start,Math.min(end,value.length));
 if(key==='clear')return {value:'',cursor:0};
 if(key==='backspace'){if(start===end)start=Math.max(0,start-1);return {value:value.slice(0,start)+value.slice(end),cursor:start}}
 if(!/^\d$|^[:,]$/.test(key))return {value,cursor:end};
 const rest=value.slice(0,start)+value.slice(end);
 if(key===':'&&rest.includes(':'))return {value,cursor:value.indexOf(':')+1};
 return {value:value.slice(0,start)+key+value.slice(end),cursor:start+1};
}
export function rateRaw(p,selected,answer){return p.kind==='choice'?selected[0]??'':p.kind==='select'?selected:p.kind==='common-gcf'?{selected,answer}:answer}
export function rateTip(p){return `<div class="formula">${escape(lessons[p.topic.replace('rate-','')][0])}</div><p>${escape(lessons[p.topic.replace('rate-','')][1])}</p>`}
